# C3 reference boundaries from the R package gsDesign (DESIGN.md section 4, C3(d)).
# Output: results/gsdesign_boundaries.csv
# The boundaries are generated by the package. They are not typed in by hand.
#
# gsDesign's alpha argument is ONE-SIDED. For a symmetric two-sided test at
# two-sided level a, pass alpha = a / 2 (0.025 gives 0.05 two-sided; 0.005 gives 0.01).
#
# Run from the repository root:  Rscript src/c3_validate_R.R

suppressPackageStartupMessages(library(gsDesign))

K <- 5
timing <- (1:K) / K
specs <- list(
  list(name = "OBF", sf = sfLDOF, two_sided = 0.05, one_sided = 0.025),
  list(name = "Pocock", sf = sfLDPocock, two_sided = 0.05, one_sided = 0.025),
  list(name = "OBF", sf = sfLDOF, two_sided = 0.01, one_sided = 0.005),
  list(name = "Pocock", sf = sfLDPocock, two_sided = 0.01, one_sided = 0.005)
)

rows <- list()
for (s in specs) {
  # Two different effect sizes (delta) to show the boundaries do not depend on delta.
  g1 <- gsDesign(k = K, test.type = 2, alpha = s$one_sided, beta = 0.1,
                 timing = timing, sfu = s$sf, sfl = s$sf, delta = 1, n.fix = 1000)
  g2 <- gsDesign(k = K, test.type = 2, alpha = s$one_sided, beta = 0.1,
                 timing = timing, sfu = s$sf, sfl = s$sf, delta = 2.5, n.fix = 1000)
  cat(sprintf("%s two-sided %.2f: max |upper bound| difference between delta=1 and delta=2.5 = %.2e\n",
              s$name, s$two_sided, max(abs(g1$upper$bound - g2$upper$bound))))
  # Null crossing probability at each look, computed from the bounds themselves.
  # The sum over looks should equal the two-sided alpha (a check of the spending).
  gp <- gsProbability(k = K, theta = 0, n.I = timing, a = -g1$upper$bound, b = g1$upper$bound)
  null_cross <- gp$upper$prob + gp$lower$prob
  cat(sprintf("  %s two-sided %.2f: total null crossing probability = %.6f\n",
              s$name, s$two_sided, sum(null_cross)))
  # Assertion (added 2026-10-30): the spending must add up to the two-sided alpha.
  stopifnot(abs(sum(null_cross) - s$two_sided) < 1e-6)
  for (k in 1:K) {
    rows[[length(rows) + 1]] <- data.frame(
      spending = s$name,
      two_sided_alpha = s$two_sided,
      look = k,
      timing = timing[k],
      upper_z = g1$upper$bound[k],
      null_cross_prob_this_look = null_cross[k],
      null_cross_prob_total = sum(null_cross),
      gsdesign_version = as.character(packageVersion("gsDesign"))
    )
  }
}
out <- do.call(rbind, rows)
dir.create("results", showWarnings = FALSE)
write.csv(out, "results/gsdesign_boundaries.csv", row.names = FALSE)
print(out)
